"use client";
/* Ufo, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Ufo(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("ufo"); }, []);
  return React.createElement("piix-sprite", { "name": "ufo", ...piixAttrs(props) });
}

export default Ufo;
